import{_ as d,C as g,o as n,c as u,a0 as r,b as s,w as t,a as i,E as l,a1 as c,j as a}from"./chunks/framework.DYS8d9tm.js";const S=JSON.parse('{"title":"📥 Precision Data Ingestion Flow","description":"","frontmatter":{},"headers":[],"relativePath":"technical/architecture/ingestion.md","filePath":"technical/architecture/ingestion.md"}'),p={name:"technical/architecture/ingestion.md"};function m(h,e,A,f,P,b){const o=g("Mermaid");return n(),u("div",null,[e[3]||(e[3]=r('<h1 id="📥-precision-data-ingestion-flow" tabindex="-1">📥 Precision Data Ingestion Flow <a class="header-anchor" href="#📥-precision-data-ingestion-flow" aria-label="Permalink to &quot;📥 Precision Data Ingestion Flow&quot;">​</a></h1><p>WealthFam features a sophisticated, multi-channel ingestion pipeline designed to minimize manual entry while maintaining 100% data accuracy through idempotent hashing and tiered parsing logic.</p><hr><h2 id="⚡-multi-channel-ingestion" tabindex="-1">⚡ Multi-Channel Ingestion <a class="header-anchor" href="#⚡-multi-channel-ingestion" aria-label="Permalink to &quot;⚡ Multi-Channel Ingestion&quot;">​</a></h2><p>Our system captures data from three primary streams:</p><ol><li><strong>Mobile SMS Ingestion</strong>: Real-time capture of bank transaction alerts directly from Android background listeners.</li><li><strong>Email IMAP Sync</strong>: Periodic scanning of authorized email accounts for bank statements and CAMS PDFs. <ul><li><strong>Automated Statement Capture</strong>: Automatically identifies, downloads, and pre-processes bank statement PDFs (e.g., HDFC, Swiggy HDFC) from incoming emails.</li></ul></li><li><strong>Manual Web Ingestion</strong>: High-fidelity bulk uploads via CSV, Excel, or PDF files through the desktop dashboard.</li></ol><hr><h2 id="🏗️-the-pipeline-lifecycle" tabindex="-1">🏗️ The Pipeline Lifecycle <a class="header-anchor" href="#🏗️-the-pipeline-lifecycle" aria-label="Permalink to &quot;🏗️ The Pipeline Lifecycle&quot;">​</a></h2>',8)),(n(),s(c,null,{default:t(()=>[l(o,{id:"mermaid-41",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Raw%20as%20Raw%20Source%20(Mobile%2FEmail%2FWeb)%0A%20%20%20%20participant%20B%20as%20Backend%20Service%20(%3A8000)%0A%20%20%20%20participant%20P%20as%20Stateless%20Parser%20(%3A8001)%0A%20%20%20%20participant%20D%20as%20TransactionDeduplicator%0A%20%20%20%20participant%20PG%20as%20PostgreSQL%20Ledger%20(%3A5432)%0A%0A%20%20%20%20Raw-%3E%3EB%3A%20Ingestion%20Request%20(SMS%20%2F%20Email%20%2F%20File)%0A%20%20%20%20B-%3E%3EB%3A%20User%20Ignore%20Rules%20%26%20Pre-Filter%20Check%0A%20%20%20%20%0A%20%20%20%20B-%3E%3EP%3A%20POST%20%2Fv1%2Fingest%2F*%20(Internal%20HTTP%20%2B%20JWT)%0A%20%20%20%20P-%3E%3EP%3A%20Check%20RecentSubmissionCache%20(5-min%20in-memory%20LRU)%0A%20%20%20%20P-%3E%3EP%3A%20FinancialClassifier%20(Filter%20OTPs%20%2F%20Promos)%0A%20%20%20%20P-%3E%3EP%3A%20Native%20Bank%20Parser%20Registry%20(Compiled%20Regex)%0A%20%20%20%20P--%3E%3EB%3A%20Normalized%20JSON%20(amount%2C%20date%2C%20mask%2C%20merchant%2C%20ref_id)%0A%20%20%20%20%0A%20%20%20%20B-%3E%3ED%3A%20check_duplicate(tenant_id%2C%20parsed%2C%20account_id)%0A%20%20%20%20alt%20Duplicate%20Detected%20(Ref%20ID%2C%20Hash%2C%20or%203-Day%20Window)%0A%20%20%20%20%20%20%20%20D--%3E%3EB%3A%20is_duplicate%20%3D%20True%20(Enrich%20GPS%20coordinates%20if%20available)%0A%20%20%20%20%20%20%20%20B-%3E%3EPG%3A%20Log%20outcome%20%3D%20duplicate_skipped%0A%20%20%20%20else%20Unique%20Transaction%0A%20%20%20%20%20%20%20%20D--%3E%3EB%3A%20is_duplicate%20%3D%20False%0A%20%20%20%20%20%20%20%20B-%3E%3EPG%3A%20Commit%20to%20Ledger%20%2F%20Triage%20(PostgreSQL)%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=a("h3",{id:"🏦-cams-kfintech-investment-ledger",tabindex:"-1"},[i("🏦 CAMS/KFintech & Investment Ledger "),a("a",{class:"header-anchor",href:"#🏦-cams-kfintech-investment-ledger","aria-label":'Permalink to "🏦 CAMS/KFintech & Investment Ledger"'},"​")],-1)),e[5]||(e[5]=a("p",null,[i("Our investment sync handles the complex extraction from bank-issued PDFs and enforces an "),a("strong",null,"Ironclad Precision Standard"),i(" for the life of the asset.")],-1)),(n(),s(c,null,{default:t(()=>[l(o,{id:"mermaid-48",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Email%5BIMAP%20Sync%20Engine%5D%20--%3E%7CFind%20Attachments%7C%20PDF%5BCAMS%2FKFintech%20PDF%5D%0A%20%20%20%20PDF%20--%3E%7CSecure%20Password%7C%20Extraction%5BPrecision%20Extraction%20Microservice%5D%0A%20%20%20%20Extraction%20--%3E%7CMask%20PII%7C%20Anonymized%5BAnonymized%20JSON%5D%0A%20%20%20%20Anonymized%20--%3E%7CMapping%7C%20Positions%5BInvestment%20Positions%5D%0A%20%20%20%20Positions%20--%3E%7CDecimal%20Rebuild%7C%20Hardened%5BHardened%20Investment%20Ledger%5D%0A%20%20%20%20Hardened%20--%3E%7CXIRR%20Engine%7C%20UI%5BDashboard%20Portfolio%20View%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=r('<p>For a deep-dive into the CAMS/KFintech extraction logic, see the <strong><a href="./../data ingestion/cas_ingestion.html">CAS Ingestion Technical Specification</a></strong>.</p><h4 id="the-hardened-ledger-principles" tabindex="-1"><strong>The Hardened Ledger Principles</strong> <a class="header-anchor" href="#the-hardened-ledger-principles" aria-label="Permalink to &quot;**The Hardened Ledger Principles**&quot;">​</a></h4><ol><li><strong>Identity Preservation</strong>: Unlike traditional systems that delete and recreate holdings during a sync, WealthFam performs <strong>In-Place Updates</strong>. This preserves the internal UUID of your holdings, ensuring that your linked <strong>Investment Goals</strong>, historical charts, and frontend caches never break (Zero 404 Resilience).</li><li><strong>Absolute Decimal Precision</strong>: Every NAV, unit count, and cost-basis calculation is performed via Python&#39;s <code>Decimal</code> library. This eliminates the &quot;Floating Point Drift&quot; common in financial apps, where rounding errors accumulate over hundreds of SIP transactions.</li><li><strong>Non-Destructive Management (Soft-Delete)</strong>: Manual cleanup of &quot;junk&quot; data or correction of duplicate CAMS entries is non-destructive. Transactions are marked with <code>is_deleted</code>, allowing for a full audit trail and the ability to &quot;un-delete&quot; historical data.</li></ol><h4 id="the-what-if-impact-analysis" tabindex="-1"><strong>The &#39;What-If&#39; Impact Analysis</strong> <a class="header-anchor" href="#the-what-if-impact-analysis" aria-label="Permalink to &quot;**The &#39;What-If&#39; Impact Analysis**&quot;">​</a></h4><p>When a user attempts to surgically delete a transaction or a folio, the system invokes the <strong>Predictive Projection Engine</strong>:</p><ul><li><strong>Step 1</strong>: It creates a transient, in-memory clone of the holding&#39;s order history.</li><li><strong>Step 2</strong>: It applies the proposed deletion to the clone.</li><li><strong>Step 3</strong>: It re-executes the IRR and Average Cost algorithms on the transient data.</li><li><strong>Step 4</strong>: It broadcasts the delta (e.g., &quot;Profit will drop by ₹540, XIRR will rise to 14.2%&quot;) to the UI <em>before</em> the user commits the change.</li></ul><h3 id="📱-real-time-sms-triage" tabindex="-1">📱 Real-Time SMS Triage <a class="header-anchor" href="#📱-real-time-sms-triage" aria-label="Permalink to &quot;📱 Real-Time SMS Triage&quot;">​</a></h3><p>How we handle incoming bank alerts with varying degrees of certainty.</p>',8)),(n(),s(c,null,{default:t(()=>[l(o,{id:"mermaid-106",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20App%20as%20Android%20Listener%0A%20%20%20%20participant%20B%20as%20Backend%20Gateway%20(%3A8000)%0A%20%20%20%20participant%20P%20as%20Stateless%20Parser%20(%3A8001)%0A%20%20%20%20participant%20PG%20as%20PostgreSQL%20Ledger%20(%3A5432)%0A%0A%20%20%20%20App-%3E%3EB%3A%20Encrypted%20SMS%20%2B%20GPS%20(POST%20%2Fapi%2Fv1%2Fmobile%2Fsms)%0A%20%20%20%20B-%3E%3EP%3A%20POST%20%2Fv1%2Fingest%2Fsms%20(In-Memory%20Parse)%0A%20%20%20%20P--%3E%3EB%3A%20Extracted%20Transaction%20JSON%0A%20%20%20%20%0A%20%20%20%20B-%3E%3EB%3A%20Deduplication%20%26%20Confidence%20Evaluation%0A%20%20%20%20alt%20High%20Confidence%20%26%20Linked%20Account%0A%20%20%20%20%20%20%20%20B-%3E%3EPG%3A%20Auto-Commit%20to%20Ledger%0A%20%20%20%20%20%20%20%20B--%3E%3EApp%3A%20Push%20Confirmation%20(Ledger%20Created)%0A%20%20%20%20else%20Unlinked%20Account%20or%20Low%20Confidence%0A%20%20%20%20%20%20%20%20B-%3E%3EPG%3A%20Save%20to%20Pending%20Triage%20(PendingTransaction)%0A%20%20%20%20%20%20%20%20B--%3E%3EApp%3A%20Notification%20(Needs%20Review%20in%20Triage)%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[i(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=r('<hr><h2 id="🛡️-key-technical-features" tabindex="-1">🛡️ Key Technical Features <a class="header-anchor" href="#🛡️-key-technical-features" aria-label="Permalink to &quot;🛡️ Key Technical Features&quot;">​</a></h2><h3 id="_1-two-tier-deduplication-idempotency" tabindex="-1">1. Two-Tier Deduplication &amp; Idempotency <a class="header-anchor" href="#_1-two-tier-deduplication-idempotency" aria-label="Permalink to &quot;1. Two-Tier Deduplication &amp; Idempotency&quot;">​</a></h3><ul><li><strong>Fast-Path (Parser LRU)</strong>: <code>RecentSubmissionCache</code> maintains an in-memory 5-minute sliding TTL of payload SHA-256 hashes, returning <code>status: &quot;duplicate_submission&quot;</code> with 0 ms disk I/O.</li><li><strong>Ledger-Path (Backend PostgreSQL)</strong>: <code>TransactionDeduplicator</code> matches normalized Ref/UTR IDs, canonical content hashes, and a resilient 3-day window (<code>[date - 1d, date, date + 1d]</code>) with fuzzy vendor token matching. If a duplicate has GPS coordinates, the existing ledger row is enriched.</li></ul><h3 id="_2-purely-stateless-in-memory-engine" tabindex="-1">2. Purely Stateless In-Memory Engine <a class="header-anchor" href="#_2-purely-stateless-in-memory-engine" aria-label="Permalink to &quot;2. Purely Stateless In-Memory Engine&quot;">​</a></h3><p>All transaction extraction runs in memory through compiled Python parsers covering 23+ Indian banks and 100+ regexes. Zero customer financial data or raw alerts are saved on disk in the parser microservice, completely eliminating DuckDB lock contention. Scrubbed metrics are asynchronously shipped to Admin DuckDB.</p><h3 id="_4-bank-statement-ingestion-automation" tabindex="-1">4. Bank Statement Ingestion &amp; Automation <a class="header-anchor" href="#_4-bank-statement-ingestion-automation" aria-label="Permalink to &quot;4. Bank Statement Ingestion &amp; Automation&quot;">​</a></h3><p>WealthFam supports bulk ingestion of bank statements (PDF/CSV) with automated classification rule generation.</p><p>For a detailed architectural breakdown of the PDF parsing algorithm, see the <strong><a href="./../data ingestion/statement_ingestion.html">Statement Ingestion Deep Dive</a></strong>.</p><ul><li><strong>Deep Table Parsing</strong>: Specialized parsers (e.g., <code>swiggy_hdfc.py</code>) extract data from complex bank PDF layouts.</li><li><strong>Automated Rule Generation</strong>: During ingestion, users can opt to save a classification rule based on the transaction&#39;s description.</li><li><strong>Session Isolation (Persistence Hardening)</strong>: To prevent data corruption during bulk operations, rules are &quot;expunged&quot; from the active database session after creation. This ensures that the Python-level object state (e.g., list of keywords) does not conflict with the database&#39;s storage format (e.g., JSON strings) during secondary commits.</li></ul><h2 id="🛠️-deep-how-to-troubleshooting-ingestion" tabindex="-1">🛠️ Deep How-To: Troubleshooting Ingestion <a class="header-anchor" href="#🛠️-deep-how-to-troubleshooting-ingestion" aria-label="Permalink to &quot;🛠️ Deep How-To: Troubleshooting Ingestion&quot;">​</a></h2><p>If a transaction from an SMS or Email fails to appear in your ledger:</p><h3 id="step-1-inspect-the-unified-ingestions-feed" tabindex="-1">Step 1: Inspect the Unified Ingestions Feed <a class="header-anchor" href="#step-1-inspect-the-unified-ingestions-feed" aria-label="Permalink to &quot;Step 1: Inspect the Unified Ingestions Feed&quot;">​</a></h3><ol><li>Navigate to <strong>Settings → Ingestions</strong> (<code>GET /api/v1/ingestion/activity</code>, default range <strong>Today</strong>).</li><li>Filter by <strong>Source</strong> (<code>SMS</code> / <code>EMAIL</code>), <strong>Person</strong>, <strong>Device / Mailbox</strong>, <strong>Account</strong>, <strong>Outcome</strong>, or <strong>Search</strong>, and click <strong>View Content</strong> to read the exact message body.</li><li>Follow the plain-English outcome CTA: <ul><li><code>blocked_unlinked_account</code> → Link the missing account mask in <strong>Accounts</strong>.</li><li><code>moved_to_triage</code> → Assign or confirm the category in <strong>Categories → Category Rules</strong>.</li><li><code>ignored_by_rule</code> → Click <strong>Allow</strong> if a user ignore rule blocked a legitimate message.</li></ul></li></ol><h3 id="step-2-check-pre-extraction-filtering-deduplication" tabindex="-1">Step 2: Check Pre-Extraction Filtering &amp; Deduplication <a class="header-anchor" href="#step-2-check-pre-extraction-filtering-deduplication" aria-label="Permalink to &quot;Step 2: Check Pre-Extraction Filtering &amp; Deduplication&quot;">​</a></h3><ul><li>User ignore rules (<code>SpamFilter</code> / <code>IgnoredPattern</code>) run in <code>Backend</code> via <code>IngestionService.check_ignore_rules()</code> before calling <code>Parser</code>.</li><li>Promotional and OTP emails are filtered strictly by <code>FinancialClassifier.is_financial(..., source=&quot;EMAIL&quot;)</code> and structured email bank parsers without loose fallback fabrication.</li></ul><h3 id="step-3-submit-anonymized-samples-tune-rules-operators" tabindex="-1">Step 3: Submit Anonymized Samples &amp; Tune Rules (Operators) <a class="header-anchor" href="#step-3-submit-anonymized-samples-tune-rules-operators" aria-label="Permalink to &quot;Step 3: Submit Anonymized Samples &amp; Tune Rules (Operators)&quot;">​</a></h3><ol><li>End users seeing <code>unrecognized_alert</code> in <strong>Settings → Ingestions</strong> (or <strong>Mobile → Ingestions</strong>) can preview PII masking and submit a consented sample via <code>POST /api/v1/ingestion/anonymize-preview</code> and <code>POST /api/v1/ingestion/report-unrecognized</code> (proxied to <code>settings.ADMIN_API_V1_URL</code>).</li><li>Operators inspect incoming samples, test templates in the sandbox, and manage regex patterns in <strong>Admin-Web → Parser Studio</strong> (Port <code>8080</code> / <code>:5174</code>).</li></ol><hr><h2 id="🏛️-separation-of-concerns-consumer-invisibility-vs-dedicated-operations-portal" tabindex="-1">🏛️ Separation of Concerns: Consumer Invisibility vs. Dedicated Operations Portal <a class="header-anchor" href="#🏛️-separation-of-concerns-consumer-invisibility-vs-dedicated-operations-portal" aria-label="Permalink to &quot;🏛️ Separation of Concerns: Consumer Invisibility vs. Dedicated Operations Portal&quot;">​</a></h2><p>A core architectural tenet of WealthFam is that <strong>a consumer end-user should never see internal parser concepts, regexes, or parser microservice routes</strong>.</p><ol><li><p><strong>Consumer Experience (<code>Web-App</code> &amp; <code>Mobile-App</code>)</strong>:</p><ul><li>Zero <code>/parser</code> proxies (<code>parserClient</code>/<code>parserApi</code> and <code>ParserSettings.vue</code> removed); consumer apps talk only to <code>Backend</code> (<code>:8000</code>).</li><li>Ingestion surfaces through plain-English <strong>Ingestions</strong> activity feeds displaying full SMS/Email content, outcomes, <strong>Ignore / Allow</strong> controls, and PostgreSQL-backed <strong>Merchant Aliases</strong> under <strong>Categories &amp; Rules</strong>.</li><li><strong>Ground-Truth Reconciliation</strong>: Reconciling statement lines automatically promotes matching items in <code>PendingTransaction</code> triage into approved ledger entries without duplicate key rejections or <code>NoneType</code> crashes.</li><li><strong>PostgreSQL JSONB Compatibility</strong>: Classification rules generated from statement descriptions use <code>cast(keywords, String).ilike()</code> for full cross-database compatibility.</li></ul></li><li><p><strong>Dedicated Operations Portal (<code>Admin-Backend</code> &amp; <code>Admin-Web</code>)</strong>:</p><ul><li>Internal parser debugging, built-in parser introspection, template CRUD, sandbox testing, training inbox, brand logos, and telemetry reside exclusively in the port-isolated admin console (<code>:8002</code> / <code>:8080</code>).</li></ul></li></ol><hr><div align="center"> *Accuracy Above All · Zero Manual Entry · Precision Integrity* *Made with ❤️ by WGLabz* </div>',24))])}const k=d(p,[["render",m]]);export{S as __pageData,k as default};
